//! RUST-015 HTTP-001/HTTP-002/HTTP-007/SEC-002 surface: replays the Go-owned
//! process fixture `testdata/port/http/http-surface-process.json` (generated by
//! `cmd/symdesk/http_surface_port_test.go` from the real Go `symdesk serve`)
//! against the Rust server. The 21 method/path patterns are probed with every
//! method and credential class, and the ServeMux path-cleaning, escape and
//! subtree cases are compared with their status line, header fields, body,
//! connection behavior and the vault tree left behind.
#![cfg(unix)]

#[path = "support/http_replay.rs"]
mod http_replay;

/// Cases and steps recorded in the committed fixture. A fixture that changes
/// without these numbers changing is rejected.
const EXPECTED_CASES: usize = 25;
const EXPECTED_STEPS: usize = 613;

#[test]
fn rust_server_replays_the_go_http_surface() {
    http_replay::replay(
        env!("CARGO_BIN_EXE_symdesk"),
        include_str!("../../../testdata/port/http/http-surface-process.json"),
        EXPECTED_CASES,
        EXPECTED_STEPS,
    );
}
